quests[36281] = { id = 36281, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garnisonskampagne: Der Ring des Blutes", description = "Hey, Champion!\n\nIhr wart gerade unterwegs, als ich vorbeigeschaut habe. Ich hab da 'ne feine Sache im Ring des Blutes in Nagrand laufen. 'Ne Menge Oger warten auf den nächsten großen Kampf und es geht um viel Geld. Seid Ihr dabei?\n\nFalls Ihr die Steinbrecherarena schon für spannend haltet... Das hier ist viel, viel besser! Das wird GRANDIOS, sage ich Euch!\n\nBesucht mich in meinem Versteck, dann besprechen wir Euren großen Auftritt unter vier Augen.\n\n<Auf der beiliegenden Karte ist ein verlassener Ogerturm mit einem Geldsymbol markiert.>", sourceObjective = "Sprecht mit Gurgthock in Gurgthocks Versteck in Nagrand.", completion = "Ich werde Eure kostbare Zeit nicht verschwenden, Champion. Ich biete Euch eine einmalige Gelegenheit.", sourceObjectiveStatus = "unverified-source-field" }
quests[36282] = { id = 36282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garnisonskampagne: Der Ring des Blutes", description = "Hey, Champion!\n\nIhr wart gerade unterwegs, als ich vorbeigeschaut habe. Ich meine, egal ob Ring der Prüfung oder Steinbrecherarena, Ihr geht aus jedem Kampf als <Sieger/Siegerin> hervor! \n\nIch hab da 'ne feine Sache im Ring des Blutes in Nagrand laufen. 'Ne Menge Oger warten auf den nächsten großen Kampf und es geht um viel Geld. Seid Ihr dabei?\n\nBesucht mich in meinem Versteck, dann besprechen wir Euren großen Auftritt unter vier Augen.\n\n<Auf der beiliegenden Karte ist ein verlassener Ogerturm mit einem Geldsymbol markiert.>", sourceObjective = "Sprecht mit Gurgthock in Gurgthocks Versteck in Nagrand.", completion = "Ich werde Eure kostbare Zeit nicht verschwenden, Champion. Ich biete Euch eine einmalige Gelegenheit.", sourceObjectiveStatus = "unverified-source-field" }
quests[36283] = { id = 36283, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Vignette Boss 011 - Blightglow" }
quests[36284] = { id = 36284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein faszinierender Fungus", description = "Die Küste von Zangar beheimatet viele merkwürdige Pilzarten, von denen einige den Pilzen ähneln, die wir aus Azeroth kennen. Eine Art ist jedoch besonders faszinierend!\n\nIch nenne sie \"Zangarium Draenormycota\" wegen ihrer Dominanz im mykotischen Ökosystem Draenors. Diese Pilzart ist extrem anpassungsfähig, und man findet sie an vielen lebenden Organismen überall an der Küste von Zangar.\n\nWarum existiert sie? Welche Eigenschaften besitzt sie?\n\nUm diese Fragen zu beantworten, brauche ich zusätzliche Sporenproben.", sourceObjective = "Sammelt 12 Pilzsporen.", progress = "Habt Ihr die Sporenproben für meine Forschung gesammelt?", completion = "Ihr habt ja die Sporenproben, die ich für meine Forschung brauche! Hervorragend!\n\nDie Küste von Zangar ist ein gefährlicher Ort, wegen der Pilzmutation und all diesen Dingen.\n\nWie, das hatte ich noch nicht erwähnt? Doch doch, ganz bestimmt!\n\nAber das ist sowieso nebensächlich. Ihr seht ziemlich zäh aus, Euer Körper wird gegen fremde und absolut unbekannte Pilzstämme sicher immun sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[36285] = { id = 36285, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grabmorast", description = "Um die Natur und die Eigenschaften des Zangarium Draenormycota voll zu verstehen, muss ich diese Pilzart in einem komplexen mykotischen Gefüge studieren. Das Fungusgehirn eines Sporenriesen wäre dafür wunderbar geeignet.\n\nEs darf aber nicht einfach irgendein Sporenriese sein. Er muss groß sein... stark... und urzeitlich... ein perfektes Exemplar!\n\nIn einer Höhle tief unter der Oberfläche lebt ein uralter Sporenriese, den die Einheimischen ehrfürchtig Grabmorast nennen. Tötet das Monster, aber achtet darauf, dass das Fungusgehirn unversehrt bleibt, damit ich es für meine Forschung verwenden kann!", sourceObjective = "Beschafft das Fungusgehirn von Grabmorast.", progress = "Wenn ich kein Fungusgehirn untersuchen kann, werden die Geheimnisse des Zangarökosystems für immer ungelöst bleiben!", completion = "Oh, Ihr habt Grabmorasts Gehirn beschafft!\n\nDie Fungusstruktur ist komplett intakt – welch ein exquisites Exemplar! Nur einen Moment, dann beginne ich mit der Untersuchung.", sourceObjectiveStatus = "unverified-source-field" }
quests[36286] = { id = 36286, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Transponder 047-B", description = "Auf die Rückseite des Transponders ist eine Nachricht eingeätzt.\n\n<DRINGEND: Falls gefunden, bitte zurück an Brillux in der Nähe von Eledor. Sehr wichtig!>", sourceObjective = "Bringt den Transponder zurück zu Brillux.\n\nBereitgestellter Gegenstand:", completion = "Oh weh! Was haben wir denn hier, Kommandant?\n\n<Untersucht den Transponder.>\n\nEin wenig beschädigt, leicht verbogen und komplett verbrannt. Aber heute ist mein Glückstag!\n\nWir haben ein neues Gerät ausprobiert und dieser Transponder birgt unschätzbar wertvolle Informationen! Ich werde Bixx sagen, er soll die Koordinaten für die Kartenaufzeichnung herausholen.\n\nNur noch ein paar Teile und ich dürfte in der Lage sein, alles quer durch das ganze Tal zu teleportieren! Und ich meine ALLES!\n\nDas wird unserer Verstärkung sicher dabei helfen, sich gegen die Eiserne Horde zu stellen!", sourceObjectiveStatus = "unverified-source-field" }
quests[36287] = { id = 36287, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schnapp und weg", description = "Es ist uns gelungen, alle Daten aus dem Transponder, den Ihr geborgen habt, zu extrahieren! Damit ist unser Zielsucher komplett!\n\nJetzt fehlen nur noch ein paar letzte Teile, und schon können die praktischen Tests beginnen.\n\nEiner meiner Piloten hat ein gestrandetes Schiff der Eisernen Horde drüben am Strand gesehen. Wenn Ihr mir davon ein paar Trümmerteile bringt, kann ich das Ding hier in Gang bringen!", sourceObjective = "Sucht den Strand nach verwertbaren Trümmerteilen ab.", progress = "Keine Sorge. Wir leihen sie uns nur von der Eisernen Horde aus!", completion = "Diese Materialien waren genau das, was ich brauchte! Ich glaube, so langsam habe ich den Bogen raus, wie man mit all diesen Draenorteilen arbeitet. Ich zeige es Euch gerne, Kommandant. Ich sollte das in null Komma nichts reparieren können.\n\nOh... und denkt daran... tief durchatmen!", sourceObjectiveStatus = "unverified-source-field" }
quests[36288] = { id = 36288, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Vignette Boss 012 - Oskiira" }
quests[36289] = { id = 36289, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus den Schatten", description = "Nochmal mein'n Glückwunsch, Blutchampion! Ihr kämpft, wie ich noch keinen kämpf'n seh'n hab.\n\nWährend Ihr im Ring wart, kam einer Eurer Brüder vorbei un' bat darum, dass Ihr zu Eurer Basis zurückkehrt. Er nannte sich Bodrick Grau.", sourceObjective = "Sprecht mit Bodrick Grau in Eurer Garnison.", completion = "Wir sollten diese Azuka Klingenwut im Auge behalten. Klingt gefährlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[36290] = { id = 36290, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus den Schatten", description = "Nochmal mein'n Glückwunsch, Blutchampion! Ihr kämpft, wie ich noch keinen kämpf'n seh'n hab.\n\nWährend Ihr im Ring wart, kam einer Eurer Brüder vorbei un' bat darum, dass Ihr zu Eurer Basis zurückkehrt. Er nannte sich einen Schattenjäger.", sourceObjective = "Sprecht mit Rokhan in Eurer Garnison.", completion = "Diese Azuka Klingenwut behalt'n wir besser im Auge. Die macht nichts als Ärger.", sourceObjectiveStatus = "unverified-source-field" }
quests[36291] = { id = 36291, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Vignette Boss 014 -  Betsi Boombasket" }
quests[36292] = { id = 36292, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untersuchung der Invasion", description = "Ich werde eine kleine Einheit hinter die feindlichen Linien führen.\n\nTrefft Euch mit mir am Schreckensfels, {class}. Von dort aus können wir entscheiden, was wir als Nächstes tun.", sourceObjective = "Trefft Euch mit Thrall hinter den feindlichen Linien.", completion = "Ich bin froh, dass Ihr es geschafft habt, {name}. Es wird Zeit, sich gegen diese Invasion der Eisernen Horde zu stemmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36294] = { id = 36294, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phylarch the Evergreen A" }
quests[36295] = { id = 36295, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phylarch the Evergreen B" }
quests[36296] = { id = 36296, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phylarch der Immergrüne", sourceObjective = "Nehmt den Blutschwur von Klingenmeisterin Na'Shra an.", completion = "Seit Zehntausenden Jahren kämpfen wir Botani gegen die mächtigsten Kräfte dieser Welt, aber niemand hat Eure ungezügelte Wildheit und Widerstandkraft.\n\nIch... ich unterwerfe mich Eurer Kampfstärke. Ich werde Euch bei Eurer Kampagne, die Herrschaft über meine Welt zu erlangen, unterstützen.\n\nWenn Ihr mich haben wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[36297] = { id = 36297, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Vignette Boss 016 - Festerbloom" }
quests[36298] = { id = 36298, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Vignette Boss 017 - Sunderthorn" }
quests[36301] = { id = 36301, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tregas Schneiderset", description = "Diese Tasche ist voll von Mustern und ungewöhnlichem Schneiderwerkzeug. Auf die Innenseite der Tasche wurde der Name \"Trega\" aufgestickt.\n\nIhr erinnert Euch daran, sie in Wor'gol gesehen zu haben. Mit etwas Glück ist sie vielleicht noch dort.", sourceObjective = "Sucht Trega in Wor'gol.", progress = "Das ist ja mein Nähzeug! Ich dachte schon, ich würde es nie wiedersehen.", completion = "Ich wurde von Ogern gejagt und musste meine Tasche zurücklassen. Es scheint fast nichts zu fehlen, außer... oh nein!", sourceObjectiveStatus = "unverified-source-field" }
quests[36303] = { id = 36303, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Vignette Boss 019 - Eyeless" }
quests[36304] = { id = 36304, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Vignette Boss 022 - Gochar" }
quests[36305] = { id = 36305, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Vignette Boss 023 - Gobblefin" }
quests[36306] = { id = 36306, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Vignette Boss 024 - Jiasska the Sporegorger" }
quests[36307] = { id = 36307, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untersuchung der Invasion", description = "Ich werde einen kleinen Trupp hinter die feindlichen Linien führen.\n\nTrefft mich beim Schreckensfels, {class}. Von dort aus werden wir über die nächsten Schritte entscheiden.", sourceObjective = "Trefft Maraad hinter den feindlichen Linien.", completion = "Ich bin froh, dass Ihr es geschafft habt, {name}. Es wird Zeit, dass wir diese Invasion der Eisernen Horde zurückschlagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36308] = { id = 36308, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzauberte Hochfelsarmschienen", description = "Eine mächtige Magie entströmt diesen Hochfelsarmschienen.\n\nVielleicht kann Euch Eileese Schattensang, die Rüstmeisterin für Verzauberungen in Eurer Garnison, mehr über diese Armschienen erzählen.", sourceObjective = "Bringt diese Armschienen zu Eileese Schattensang in Eurer Garnison.\n\nBereitgestellter Gegenstand:", completion = "Interessant... Vor Kurzem hat ein Arakkoa die Garnison aufgesucht. Er fragte nach Rüstungsteilen mit einem starken Zauber wie diesem. Sein Name war Delath.\n\nDie Verzauberung auf diesen Armschienen übersteigt meine Fähigkeiten, aber vielleicht kann dieser Delath Euch erzählen, wie man sie replizieren kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[36309] = { id = 36309, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Stärke des Eisens", description = "An der Seite des Ranzens ist ein aufgenähter Flicken, der den Besitzer eindeutig identifiziert.\n\nIhr erinnert Euch daran, Geschichten über einen großartigen Schmied nördlich von Embaari gehört zu haben.", sourceObjective = "Bringt den Ranzen zu Haephest.\n\nBereitgestellter Gegenstand:", completion = "Das... das ist mein Ranzen. Aber wie...?\n\nHabt Ihr einen Jungen gesehen? Einen kleinen Jungen in der Nähe von dem Ranzen? Ihr müsst mir sagen, wo Ihr ihn gefunden habt!\n\nIch habe versucht, gegen die Plünderer zu kämpfen... aber sie waren zu stark! Sie haben mich fast umgebracht!\n\nBitte, bitte...\n\nIch würde alles darum geben, meinen einzigen Sohn wiederzuhaben! Ich darf ihn nicht im Stich lassen...", sourceObjectiveStatus = "unverified-source-field" }
quests[36310] = { id = 36310, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Arakkoaverzauberer", description = "Der Arakkoa sagte, er würde eine Anomalie am Vergessenen Strand untersuchen, die mit einem weiteren Rüstungsteil zu tun haben könnte.", sourceObjective = "Findet Delath am Vergessenen Strand im Süden.", progress = "Seid gegrüßt, Verzauberer. Ich sehe, dass Ihr mit dieser Kunst vertraut seid. \n\nSehr gut. Vielleicht können wir uns gegenseitig helfen.", completion = "Gehe ich weiterhin recht in der Annahme, dass Ihr ein Artefakt unseres Lands in Eurem Besitz habt?\n\nDarf ich es sehen?\n\nEine von Oru'kais Armschienen... Ich danke Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[36311] = { id = 36311, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vater und Sohn", description = "Bitte findet meinen Jungen!\n\nWir waren in den Bergen, gleich nordöstlich von hier, als die Plünderer kamen.\n\nEs waren nicht viele, aber ich bin ein Schmied, kein Krieger!\n\nHabe ich etwa meinen eigenen Sohn im Stich gelassen?", sourceObjective = "Findet Haephests Sohn.", completion = "Mein Junge!\n\n<Eine Träne läuft ihm die Wange herunter und bahnt sich einen Weg durch die Rußschicht auf seiner Haut.>\n\nIch... Ich kann mit Worten nicht sagen, wie dankbar ich Euch bin.\n\nIch möchte versuchen, Euch etwas zurückzuzahlen, aber ich besitze kaum Wertgegenstände. Die meisten meiner Werke kommen den Soldaten zugute. Aber ich verfüge über das Wissen meines Volkes und meines Handwerks.\n\nEs wäre mir eine Ehre, wenn ich Euch einen Teil dieses Wissens lehren dürfte.\n\nMöge das Licht Euch leiten, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[36312] = { id = 36312, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Vignette Boss 025 - Sun Sage Valarik" }
quests[36313] = { id = 36313, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Versagen der Schülerin", description = "Oru'kai war der erste Ogermagier auf Draenor, der die Verzauberkunst gemeistert hat. Nach seinem Tod wurden seine Besitztümer über Draenor verstreut. Ich habe seinen Stab zu der Küstenlinie zurückverfolgt, die vor uns liegt.\n\nWie Ihr seht, macht es die Verzauberung des Stabs schwer, ihn zu bergen. Ein angehender Lehrling namens Deema nahm einen von Oru'kais Ringen, um die Verzauberung zu brechen, aber sie schaffte es nicht und wurde ebenfalls gefangen.\n\nSucht nach Deema und befreit sie, nehmt den Ring und bringt ihre Aufgabe zu Ende. Dann werde ich eine Belohnung in Erwägung ziehen.", sourceObjective = "Findet und befreit Deema aus ihrem Zeitgefängnis.", completion = "Danke! Ich dachte schon, ich müsste ewig hier bleiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[36314] = { id = 36314, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der verschlungene Anhänger", description = "Der purpurrote Edelstein, der in diesem Anhänger verarbeitet wurde, ist einzigartig, und seine Fassung stammt aus meisterlicher Handwerkskunst.\n\nIhr könnt von demjenigen, der das hier hergestellt hat, sicher viel lernen. Vielleicht erkennt jemand in Eurer Garnison die Handschrift dieser Arbeit.", sourceObjective = "Fragt in Eurer Garnison herum, ob jemand den Anhänger erkennt.", progress = "Na, aber hallo, {name}, was haben wir denn hier?", completion = "Bitte, darf ich ihn mir einmal näher ansehen?", sourceObjectiveStatus = "unverified-source-field" }
quests[36315] = { id = 36315, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oru'kais Stab", description = "Wenn ich gewusst hätte, dass es so gefährlich ist, ein Verzauberer zu sein, wäre ich in Shattrath geblieben. \n\nHier, nehmt diesen Ring. Der Arakkoa sagte mir, dass ich diesen Ring auf den Stab anwenden solle, um den Zauber aufzuheben.\n\nBringt ihm das Szepter zurück. Vielleicht wird er ja Euch lehren, was er versprochen hat, mich zu lehren.", sourceObjective = "Nehmt Oru'kais Stab an Euch und bringt ihn Delath zurück.", progress = "Der Stab! Gebt ihn mir!", completion = "Ja... Das ist es, nach so vielen Jahren. Bald werde ich alle Waffen Oru'kais haben.\n\nBringt meinen Ring ebenfalls zurück und ich werde das Versprechen halten, das ich dieser zart besaiteten Draenei gegeben habe.\n\nNehmt dieses Buch. Wenn Ihr geschickt seid, könnt Ihr es nutzen, um Draenors Verzauberungen zu entschlüsseln und zu erlernen.\n\nNatürlich werdet Ihr einen vernünftigen Arbeitsplatz benötigen. Hier sind Pläne, denen Ihr hoffentlich folgen könnt.\n\nJetzt geht und haltet Euch von den anderen Waffen fern, denn die gehören mir.", sourceObjectiveStatus = "unverified-source-field" }
quests[36316] = { id = 36316, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Sieg ist nahe", description = "Wir haben den Jüngern einen harten Schlag versetzt, aber der Kampf ist noch nicht entschieden.\n\nSammelt Eure Verbündeten und macht Euch bereit für die Belagerung der Himmelsnadel!\n\n\"Der Schatten wächst, wenn der Rabe den Tag verschlingt.\n\nDas brennende Firmament ist nimmermehr, wenn die schwarzen Schwingen sich sanft über dem Himmel ausbreiten.\n\nSchlaft jetzt, meine Kinder, schlaft. Denn selbst die Sonne muss einmal ruhen.\"\n\nDies war Rukhmars Wiegenlied, das sie ihren ersten Arakkoa vorgesungen hat. Oh, wie weit sind wir vom Weg abgekommen.", sourceObjective = "Tötet Ranjit, Araknath, Rukhran und die Oberste Weise Viryx in der Himmelsnadel.", completion = "Vielleicht besteht jetzt ja Hoffnung auf eine bessere Zukunft. Ich hoffe nur, dass der eine oder andere in Himmelsnadel erweckt wurde.", sourceObjectiveStatus = "unverified-source-field" }
