quests[36338] = { id = 36338, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf den Hafen von Shattrath" }
quests[36340] = { id = 36340, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Treasure 058 - Ogron Plunder" }
quests[36341] = { id = 36341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urzorn", description = "Jetzt scheint es so weit zu sein, Kommandant.\n\nWir müssen die Eiserne Horde um jeden Preis aufhalten. Ich habe Sturmkrähen zu Eurer Garnison geschickt und Bodrick Grau gebeten, Eure Truppen unverzüglich zu den Toren von Tanaan zu verlegen.\n\nWenn Ihr im nördlichen Talador eintrefft, sollte er bereits auf Euch warten... und zwar mit einer ganzen Armee.\n\nLos, verliert keine Zeit.", sourceObjective = "Trefft Euch mit Bodrick Grau nahe der Tore von Tanaan in Talador und besiegt dann Gorgorek und Kriegsfürstin Azuka Klingenwut.", completion = "Euren Heldentaten scheinen keine Grenzen gesetzt, {name}. Heute haben Eure Garnisonstruppen dem Kriegshäuptling Höllschrei und der Eisernen Horde einen schweren Schlag versetzt.\n\nAllerdings ist ihm so leicht nicht beizukommen. Sein Rachedurst wird jetzt wahrscheinlich noch größer werden.\n\nWir müssen die Wurzel seiner Operation im Tanaandschungel herausreißen. Doch zunächst müssen noch viele Vorbereitungen getroffen werden.\n\nBis dahin, genießt Euren errungenen Teilsieg.", sourceObjectiveStatus = "unverified-source-field" }
quests[36342] = { id = 36342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urzorn", description = "Jetzt scheint es so weit zu sein, Kommandant.\n\nWir müssen die Eiserne Horde um jeden Preis aufhalten. Ich habe Sturmkrähen zu Eurer Garnison geschickt und Schattenjäger Rokhan gebeten, Eure Truppen unverzüglich zu den Toren von Tanaan zu verlegen.\n\nWenn Ihr im nördlichen Talador eintrefft, sollte er bereits auf Euch warten... und zwar mit einer ganzen Armee.\n\nLos, verliert keine Zeit.", sourceObjective = "Sprecht mit Schattenjäger Rokhan im nördlichen Talador und besiegt dann Gorgorek und Kriegsfürstin Azuka Klingenwut.", completion = "Euren Heldentaten scheinen keine Grenzen gesetzt, {name}. Heute habt Ihr mit Euren Garnisonstruppen Kriegshäuptling Höllschrei und der Eisernen Horde einen schweren Schlag versetzt.\n\nAllerdings ist ihm so leicht nicht beizukommen. Sein Durst nach Rache wird jetzt sicher noch größer werden.\n\nWir müssen die Wurzel seiner Operation im Tanaandschungel herausreißen. Doch zunächst müssen noch viele Vorbereitungen getroffen werden.\n\nGenießt bis dahin Euren errungenen Teilsieg.", sourceObjectiveStatus = "unverified-source-field" }
quests[36344] = { id = 36344, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Versorgung einer Armee", description = "Wir hatten jetzt eine Weile die Gelegenheit, mit diesen Tieren zu arbeiten. Das hat uns in die Lage versetzt, eine brandneue Falle für Euch zu bauen, die Ihr ausprobieren könnt. Sie sollte wesentlich widerstandsfähiger sein als die letzte!\n\nMit der verbesserten Eisenfalle könnt Ihr einige der fleischigeren Tiere von Draenor einfangen. Ihr werdet entdecken, dass eine einzelne Flussbestie oder ein Eber aus Gorgrond die Mägen vieler Krieger füllen kann.\n\nFangt eins dieser Tiere und bringt es zurück, dann werden wir ein wildes Mahl für Euch zubereiten.", sourceObjective = "Benutzt die verbesserte Eisenfalle, um einen Eber oder eine Flussbestie in Gorgrond zu fangen und erteilt dann in Eurer Scheune einen Arbeitsauftrag.", completion = "Die Falle hat also gehalten! Ich kann das Fleisch schon riechen. Es wird einen Festschmaus für unsere Krieger abgeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[36345] = { id = 36345, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einstieg in die Fallenstellerei", description = "Als wir durch das Portal gereist sind, konnten wir keines unserer Tiere mitnehmen. Um Leder und Felle zu produzieren, müssen wir also die einheimischen Tiere mit Fallen fangen und hierher zurückbringen.\n\nDie Ebenen sind zwar eisig, es gibt jedoch viele Grollhufe und Wölfe im Frostfeuergrat. Wir können Leder von den Grollhufen oder Felle von den Wölfen gewinnen.\n\nHier, nehmt diese Eisenfalle und fangt damit ein ausgewachsenes verwundetes Tier. Bringt die Falle zurück zu uns, dann werden wir unsere Arbeit beginnen.", sourceObjective = "Benutzt die Eisenfalle, um einen Grollhuf oder Wolf im Frostfeuergrat zu fangen und erteilt dann in Eurer Scheune einen Arbeitsauftrag.", completion = "Sehr gut. Wir werden schon bald genug Leder und Felle für Euch zusammenhaben.\n\nDa Ihr jetzt die Verwendung der Falle erlernt habt, wird sie Euch jederzeit zur Verfügung stehen. Da wir in der Scheune allerdings nur eine begrenzte Anzahl Tiere verarbeiten können, würde ich Euch raten, dem Land nicht mehr als notwendig zu nehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36346] = { id = 36346, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Größere Falle, bessere Ausbeute", description = "Ah, Kommandant, schön, Euch wiederzusehen. Aus den hier in Draenor gesammelten Materialien konnten wir eine Falle konstruieren, die selbst die stärksten Tiere fest im Griff hält.\n\nSolch große, starke Tiere finden sich auf der Westseite von Nagrand, auf den fruchtbaren Ebenen.\n\nAber ich muss Euch warnen: Diese Tiere sind wirklich sehr stark und wehrhaft. Vielleicht wollt Ihr lieber ein paar Freunde mit auf die Jagd nehmen.", sourceObjective = "Benutzt die tödliche Eisenfalle, um einen Eisenfellbullen, Terrorzahnalpha oder Sumpflandtrampler einzufangen.", completion = "Blut und Donner! Das muss ja ein gigantischer Kampf gewesen sein!\n\nMit den Materialien, die wir aus diesen Tieren gewinnen können, werden wir eine ganze Weile auskommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36347] = { id = 36347, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf Socrethars Klippe" }
