quests[36352] = { id = 36352, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach dem Edelsteinexperten", description = "Sicher, dass Ihr mir den nicht überlassen wollt? Ich zahle auch anständig dafür!\n\nAlso gut... Wenn Ihr unbedingt den rechtmäßigen Besitzer finden wollt, solltet Ihr vielleicht nach Wor'gol gehen.\n\nEs heißt, dass dort ein Meisterhandwerker lebt, der sich auf die Bearbeitung wertvoller Metalle und Steine versteht. Der könnte Euch vielleicht weiterhelfen.", sourceObjective = "Sucht in Wor'gol nach dem Besitzer des Anhängers.", completion = "{race}, wie kann ich mich dafür erkenntlich zeigen, dass Ihr mir den Anhänger zurückgebracht habt?", sourceObjectiveStatus = "unverified-source-field" }
quests[36353] = { id = 36353, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Um der alten Zeiten willen", sourceObjective = "{name}, wir sind schon so oft zusammen durch Himmel und Hölle gegangen, dass ich es kaum noch zählen kann. Ihr seid die größte Hoffnung der Allianz im Kampf gegen die Horde. Aber das wisst Ihr ja selbst.\n\nWas haltet Ihr davon, wenn ich mich Eurer Garnison anschließe? Zusammen können wir den Orcabschaum bekämpfen – ganz wie in den guten alten Zeiten.", sourceObjectiveStatus = "unverified-source-field" }
