quests[36367] = { id = 36367, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Treasure 047 - Mayoral Campaign Contributions" }
quests[36368] = { id = 36368, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vermisster Holzfäller", description = "All diese Maulwurfmaschinen hier in Gorgrond scheinen technische Probleme zu haben. Ich hörte, dass eine von ihnen hier im Schlingenherz auseinandergefallen sein soll.\n\nVersucht, Frenna zu finden. Sie müsste diejenige sein, die wir bis hierher verfolgt haben. Ich begebe mich zu der Maulwurfmaschine, um zu sehen, ob man sie reparieren kann.", sourceObjective = "Findet Frenna im Schlingenherz.", completion = "Frenna hat es nicht aus dem Schlingenherz heraus geschafft.", sourceObjectiveStatus = "unverified-source-field" }
quests[36374] = { id = 36374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spiires - Treasure 036 - Statue of Anzu" }
quests[36375] = { id = 36375, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Treasure 026 - Sethekk Idol" }
quests[36376] = { id = 36376, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goreninvasion!", description = "Die Garnison wird von Erdbeben erschüttert, und unsere Späher sind schon seit Stunden überfällig.", sourceObjective = "Schlagt die Goreninvasion zurück.\n\n(Sprecht erneut mit Unteroffizier Krähler, um zu beginnen.)", progress = "Wir müssen die Stellung halten!", completion = "Wir haben sie vertrieben, Kommandant!", sourceObjectiveStatus = "unverified-source-field" }
quests[36377] = { id = 36377, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Treasure 049 - Rukhmar's Image" }
quests[36378] = { id = 36378, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Druck, keine Diamanten", description = "Ihr möchtet das Geheimnis unserer Edelsteine verstehen, {race}? Ihr habt mir meinen Anhänger zurückgebracht, also werde ich Euch helfen.\n\nAber ich muss Euch warnen: Die Materialien sind nicht einfach zu beschaffen.\n\nIm Norden werdet Ihr auf Magmateiche treffen, die lebende Lavakreaturen hervorbringen. In ihrem Inneren könnt Ihr prachtvolle Diamanten finden.\n\nBitte bringt mir einige davon...", sourceObjective = "Beschafft Lavadiamanten von den Lavaschleimen im Frostfeuergrat.", progress = "Habt Ihr die Materialien, um die ich Euch bat?", completion = "Dieser Diamant ist einfach wundervoll! Ich bekomme Gänsehaut bei dem Gedanken, aus welch riesiger Kreatur er stammen muss...", sourceObjectiveStatus = "unverified-source-field" }
quests[36379] = { id = 36379, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einen Blick durch das Portal erhaschen", description = "Ich habe Späherin Pazerp entsandt, damit sie sich das Portal näher anschaut. Sie hätte längst zurück sein müssen. Ich frage mich, warum das so lange dauert.\n\nSie ist eine meiner besten Späherinnen und ich mache mir Sorgen.", sourceObjective = "Findet Späherin Pazerp und verwendet ihr Teleskop.", completion = "Arme Pazerp... Das sind wirklich mehr als beunruhigende Neuigkeiten. Die Eiserne Horde scheint über unendlichen Nachschub an Truppen zu verfügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36380] = { id = 36380, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diamantenfieber", description = "Bitte seht genau hin, {name}. Ich werde diesen Edelstein zu einem feinen Anhänger für Euch verarbeiten.\n\nHoffentlich könnt Ihr dabei etwas über wahre Juwelierskunst lernen.", sourceObjective = "Wartet darauf, dass Orolak den Anhänger fertigstellt.", completion = "Vielen Dank für Eure Hilfe, {name}, bitte nehmt diesen Anhänger zusammen mit einer Abschrift meiner Forschungen.\n\nIch hoffe, dass dies Euch helfen wird, die Geheimnisse draenischer Edelsteine besser zu verstehen.\n\nBis zu unserem nächsten Treffen, mein Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[36381] = { id = 36381, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spitzen - Schreinschatz 01 - Geschenk des Anzu" }
quests[36382] = { id = 36382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einen Blick durch das Portal erhaschen", description = "Ich hab' Späher Pazaztick geschickt, damit er sich das Portal näher anschaut. Er hätt' längst zurück sein soll'n. Warum dauert das so lange?\n\nDas passiert, wenn man Goblins als Helfer anheuert.", sourceObjective = "Findet Späher Pazaztick und verwendet sein Teleskop.", completion = "Das is' nich' gut. Die Eiserne Horde macht uns hier jede Menge Ärger. Wir müss'n einen Weg finden, mit ihnen fertig zu werd'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[36383] = { id = 36383, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf die Grube", description = "Die Eiserne Horde lagert ihre Waffen und Munitionsvorräte außerhalb der Gießerei. Durch ihre Kampagne in ganz Draenor sind ihre Vorratslager angreifbar geworden. Begebt Euch dorthin und richtet so viel Chaos wie möglich an. Und verwendet auch ein bisschen ihrer eigenen Munition gegen sie, wenn sie das Zeug schon einfach herumliegen lassen!", sourceObjective = "Zerstört das Waffenlager der Eisernen Horde und schaltet so viele von ihnen aus wie möglich.", sourceObjectiveStatus = "unverified-source-field" }
quests[36384] = { id = 36384, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feldversuch", description = "Passt auf, ich habe Kimzee nichts davon erzählt, weil ich ihre Gefühle nicht verletzen möchte. Aber ich habe mich entschlossen, das Quetschpfeifenkap nicht zu verlassen.\n\nIch habe nämlich an einem Serum gearbeitet, von dem ich hoffe, dass man damit die Infizierten heilen kann. Aber als ich es testen wollte, wurde ich umzingelt und habe mich bei der Flucht am Bein verletzt.\n\nIch weiß, dass ich auf dem richtigen Wege bin, aber ich muss das Serum jetzt testen. Nehmt bitte diese Phiole und testet es an einem der Infizierten da draußen.", sourceObjective = "Begebt Euch zum Quetschpfeifenkap und benutzt die Phiole mit unerprobtem Serum bei einem infizierten Haudrauf oder einem infizierten Holzfäller, um das Serum zu testen. Kehrt dann zu Krixel Quetschpfeife zurück, um über die Ergebnisse zu berichten.", progress = "Habt Ihr schon die Feldversuche beendet, {name}?", completion = "Was hat das Serum gemacht?!\n\nIch muss wohl ein wenig zu viel von den Wachstumshormonen benutzt haben. Oder vielleicht muss die Mixtur vor der Dosierung nur gut durchgeschüttelt werden?", sourceObjectiveStatus = "unverified-source-field" }
quests[36385] = { id = 36385, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Erbe der Urtume", description = "Als Ihr den uralten Folianten öffnet, bemerkt Ihr, dass es sich nicht um ein Buch, sondern vielmehr um ein Behältnis handelt. Im Innern befinden sich vier leere Aussparungen.\n\nBei näherer Betrachtung zeigt sich, dass sich neben den Aussparungen Schnitzereien befinden, die unterschiedliche Urtume aus Draenor darstellen. Weiterhin entdeckt Ihr ein paar Glyphen und Halterungen für ein Holzstück des jeweils dargestellten Urtums sowie Hinweise auf die Aufenthaltsorte dieser Urtume: mittelgroßes Holz – Schattenmondtal, Gorgrond, die Spitzen von Arak und Nagrand.\n\nEs handelt sich hier offenbar um Mordanweisungen. Morde an Bäumen ausgeführt von Bäumen.", sourceObjective = "Besorgt Kuruks Herz, Autuks Stamm, Loruks Zweig und Hanuks Wurzeln.", progress = "Was habt Ihr denn da, Kommandant?", completion = "Ihr meint also, dass dieses Buch hier eigentlich ein Behältnis ist, indem die Überreste der Opfer einer Mordauftragsliste verwahrt werden? Und diese Morde wurden begangen von einem anderen... Baum?!\n\nDies ist eine verrückte Welt.\n\nLasst uns mal sehen, was geschieht, wenn wir alle Teile an die richtige Stelle setzen.", sourceObjectiveStatus = "unverified-source-field" }
