quests[36403] = { id = 36403, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Treasure 010 - Offering to the Raven Mother 01" }
quests[36404] = { id = 36404, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Garten aufräumen", description = "Diese Lichtung ist perfekt für den Anbau von Kräutern für unsere Garnison. Es gibt da nur ein kleines Problem: all diese verdammten Waschbären!\n\nIch möchte, dass Ihr sie vertreibt, dann können wir damit beginnen, diesen Garten zu bepflanzen.", sourceObjective = "Tötet 8 Mondsturzwaschbären.", completion = "Gute Arbeit, {name}! Wir sollten sofort damit anfangen, den Garten zu bepflanzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36405] = { id = 36405, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Treasure 051 - Offering to the Raven Mother 02" }
quests[36406] = { id = 36406, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Treasure 052 - Offering to the Raven Mother 03" }
quests[36407] = { id = 36407, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Treasure 053 - Offering to the Raven Mother 04" }
quests[36408] = { id = 36408, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verlorene Energie", description = "<Das Fragment leuchtet im Licht auf, als das letzte Pulsieren seiner Aura abklingt.>\n\nDie Energie in dem Fragment scheint erloschen.\n\nIhr erinnert Euch daran, dass einige Reisende erwähnt haben, dass jemand in Embaari sich auf das Durchwirken von Edelsteinen mit Magie spezialisiert hat.", sourceObjective = "Findet jemanden in Embaari, der sich hervorragend mit Edelsteinen und Magie auskennt.\n\nBereitgestellter Gegenstand:", completion = "Was habt Ihr da...\n\nNur ein geschultes Auge wäre in der Lage zu erkennen, welche Macht in diesem erschöpften Kristall steckt. Ihr kennt Euch vielleicht mit den Kristallen der Draenei noch nicht aus, aber es ist nicht zu leugnen, dass Ihr Euch mit Edelsteinen auskennt.\n\nIch sag Euch was... wenn Ihr mir bei den Problemen mit den hiesigen Verteidigungskristallen zur Hand geht, teile ich gerne mein Wissen der Juwelierskunst mit Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[36409] = { id = 36409, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederherstellung", description = "Wie bereits erwähnt ist die Energie unserer großen Verteidigungskristalle erschöpft, was Lücken in unserer Verteidigung aufgerissen hat. Der Kristall, den Ihr mitgebracht habt, ist nur eine Mahnung, wie ernst die Lage wirklich ist. Schuld daran ist Schattenmondmagie, da bin ich sicher.\n\nEiner unserer Rangarispäher hat einen Orc entdeckt, der nach Norden an Fahlmond vorbei in das dahinterliegende Tal floh. Geht und findet diesen Orc und versucht, das Gefäß an Euch zu bringen, in dem er die Energie aufbewahrt. Wenn wir sie zurückbekommen, bin ich zuversichtlich, dass wir die Kristalle wiederherstellen können.", sourceObjective = "Holt die Probe für Konstrukteur Baleera.", progress = "Die Energie des Kristalls pulsiert, während er getragen wird.", completion = "Ihr habt sie gefunden! Dieser Kristall sprudelt geradezu über vor Energie. Genau danach haben wir gesucht.\n\nIch wage gar nicht daran zu denken, was für ein Ritual dieser Orc wohl mit der Energie dieses Kristalls durchführen wollte.\n\nIhr habt uns einen großen Dienst erwiesen, {class}. Wie versprochen möchte ich Euch meine Dankbarkeit beweisen, indem ich Euch zeige, wie man einige der hiesigen Edelsteine und Kristalle bearbeitet. Ich bin sicher, Ihr werdet dieses Wissen sinnvoll einsetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36410] = { id = 36410, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spitzen - Schatz 054 - Opfergabe für die Rabenmutter 05" }
quests[36411] = { id = 36411, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spitzen - Schatz 014 - Ein Verlorener Ring" }
quests[36412] = { id = 36412, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasion des Schattenmondklans!", description = "Späher berichten, dass der Schattenmondklan geschäftig brummt wie ein Hornissennest, dem man einen Tritt verpasst hat. Zeit, etwas für unseren Sold zu tun, Kommandant?", sourceObjective = "Schlagt die Invasion Eurer Garnison durch den Schattenmondklan zurück.\n\n(Sprecht erneut mit Unteroffizier Krähler, um zu beginnen.)", progress = "Wir müssen die Stellung halten!", completion = "Ihr wart wie ein heller Lichtschein inmitten der Feinde, Kommandant. Sieht aus, als dürfen wir noch einen weiteren Morgen in Draenor erleben.", sourceObjectiveStatus = "unverified-source-field" }
quests[36414] = { id = 36414, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasion des Schattenmondklans!", description = "Die Späher berichten, dass die Truppen des Schattenmondklans bereits ganz in der Nähe sind und sie haben Totenbeschwörer in ihren Reihen. Sollte ich fallen und wieder auferstehen, Kommandant, dann tötet mich bitte schnell. Ich will kein Ghul sein.", sourceObjective = "Schlagt die Invasion Eurer Garnison durch den Schattenmondklan zurück.\n\n(Sprecht erneut mit Unteroffizier Grimmkinn, um zu beginnen.)", completion = "Es geht doch nichts über ein wenig rechtschaffenes Blutvergießen, um die Kälte aus diesen alten Knochen zu vertreiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[36415] = { id = 36415, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Treasure 020 - Reagent Pouch" }
quests[36416] = { id = 36416, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Treasure 049 - Misplaced Scroll" }
quests[36417] = { id = 36417, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus ihren toten, kalten Händen", description = "Diese Oger haben mir meinen ganzen Hexenzwirn weggenommen!\n\nIch hatte ihn ganz unten in meiner Tasche versteckt. Wie konnten sie überhaupt wissen, dass es etwas Wichtiges ist?\n\nWenn sie auch nur einen Bruchteil von seinen Eigenschaften entdecken, bekommen wir alle echte Probleme.\n\n{name}, das ist ein Frostwolfproblem, das eine Frostwolflösung erfordert.\n\nWerdet Ihr mir helfen?", sourceObjective = "Sammelt 10 beschädigte Hexenzwirne von Ogern der Speerspießer.", progress = "Nun, ist es getan?", completion = "Das müsste der ganze Zwirn sein. Aber sie scheinen versucht zu haben, ihn zu zerreißen, um die Magie mit purer Gewalt herauszureißen. Das sind, glaube ich, Bissspuren...", sourceObjectiveStatus = "unverified-source-field" }
quests[36418] = { id = 36418, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spitzen - Schatz 013 - Dunkler Zauberfoliant" }
quests[36419] = { id = 36419, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Fell gefärbt", description = "Unfassbar... Sie haben versucht, die Magie mit roher Gewalt aus dem Material zu reißen!\n\nOffenbar liefen wir letztlich nie Gefahr, dass meine Geheimnisse in die falschen Hände geraten würden. Aber Vorsicht ist besser als Nachsicht...\n\nAls Dank für Eure Hilfe werde ich Euch meine Methoden zur Verschmelzung der Magie mit dem Zwirn zeigen.\n\nFliegenfallensekret ist in dieser Gegend sehr selten, aber ich habe noch einen kleinen Vorrat. Nehmt dieses gewobene Fell und taucht es in das Sekret hier ein. Ihr werdet selbst sehen, wozu der ganze Aufwand gut war.", sourceObjective = "Benutzt TregasFliegenfallensekret zur Herstellung einer Bahn Hexenzwirn.", completion = "Na also, Ihr seid auf dem besten Weg, die wahre Kunst der Hexenzwirnschneiderei zu erlernen.\n\nGebt die Geheimnisse, die ich Euch gezeigt habe, an niemanden weiter.", sourceObjectiveStatus = "unverified-source-field" }
quests[36420] = { id = 36420, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Treasure 011 - Garrison Supplies" }
quests[36421] = { id = 36421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Treasure 024 - Sun-Touched Cache" }
quests[36422] = { id = 36422, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Treasure 029 - Sun-Touched Cache" }
quests[36423] = { id = 36423, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haustiere gegen Ungeziefer", description = "Ich habe versucht, hier alles für Eure Haustiere vorzubereiten, aber wir haben während des Aufbaus der Garnison ein paar widerwärtige Arten Ungeziefer entdeckt. Ich habe versucht, sie selbst zu bekämpfen, aber die sind zu zäh für mein kleines Team.\n\nIm Garten läuft eine zornige Karotte herum, eine riesige Ratte frisst unsere Lebensmittelvorräte auf und eine widerspenstige Wasserkreatur bedrängt unsere Fischer. Wenn Ihr Euch um diese Kreaturen kümmern könntet, hätte ich genug Zeit, die Arbeiten an Euren Gehegen zu Ende zu bringen.", sourceObjective = "Vernichtet die drei Ungezieferkreaturen in Eurer Garnison.", completion = "Ich danke Euch, {name}. Dann wollen wir doch mal sehen, ob Euren Haustieren ihr neues Zuhause gefällt!", sourceObjectiveStatus = "unverified-source-field" }
quests[36424] = { id = 36424, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Treasure 059 - Sun-Touched Cache" }
quests[36425] = { id = 36425, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eierball", description = "<Ein schwitziges, pulsierendes Ei, ganz sicher randvoll mit Verheererlarven.\n\nEin beherzter Tritt sollte dieses Problem beseitigen.>", sourceObjective = "Zertretet 10 Verheerereier in Dornnarbes Lager.", sourceObjectiveStatus = "unverified-source-field" }
quests[36426] = { id = 36426, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kugelduell" }
quests[36427] = { id = 36427, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Aufstieg und Fall des Barovkonzerns: Alexi Barov", sourceObjective = "Nehmt den Blutschwur von Klingenmeisterin Na'Shra an.", completion = "\"Die Brüder wieder vereint\", hat er gesagt.\n\n\"Eine Welt voller unbeschreiblicher Schätze, die man nur an sich reißen muss\", hat er gesagt.\n\n\"Unermessliche Reichtümer\", hat er gesagt!\n\nUnd als Nächstes hat er einen Baumstamm auf mich fallen lassen.\n\n\"Es kann nur einen Geschäftsführer des Barovkonzerns geben\", sagte er.\n\nZumindest in diesem Punkt sind wir uns einig...", sourceObjectiveStatus = "unverified-source-field" }
quests[36428] = { id = 36428, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmerzvolle Heilung", description = "Die Infektion wird immer stärker, weshalb ich ein paar Änderungen an dem Serum vorgenommen habe. Ich bin ziemlich sicher, dass ich jetzt die richtige Formel habe.\n\nEs sollte nun eigentlich funktionieren, aber wenn es mit zu viel infiziertem Blut vermengt wird, verringert dies die Wirksamkeit.\n\nDamit das Serum richtig wirken kann, müsst Ihr die Infizierten schwächen, bevor Ihr ihnen das Serum iinjiziert.\n\nDie Infektion entwickelt sich ständig weiter und wird bald gar nicht mehr behandelbar sein, wir haben daher nur diesen einen Versuch. Wir müssen versuchen, so viele zu retten, wie wir können.", sourceObjective = "Heilt 6 infizierte Goblins.", completion = "Ja! Gute Arbeit, {name}!\n\nIch habe schon mit einigen der Überlebenden gesprochen und sie sind froh über diese zweite Chance.\n\nIhr habt heute sehr viel Gutes getan!", sourceObjectiveStatus = "unverified-source-field" }
quests[36429] = { id = 36429, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Aufstieg und Fall des Barovkonzerns: Weldon Barov", sourceObjective = "Nehmt den Blutschwur von Klingenmeisterin Na'Shra an.", completion = "\"Die Brüder wieder vereint\", hat er gesagt.\n\n\"Eine Welt voller unbeschreiblicher Schätze, die man nur an sich reißen muss\", hat er gesagt.\n\n\"Unermessliche Reichtümer\", hat er gesagt!\n\nUnd als Nächstes hat er einen Baumstamm auf mich fallen lassen.\n\n\"Es kann nur einen Geschäftsführer des Barovkonzerns geben\", sagte er.\n\nZumindest in diesem Punkt sind wir uns einig...", sourceObjectiveStatus = "unverified-source-field" }
quests[36430] = { id = 36430, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking: Mill Treasure 18" }
quests[36431] = { id = 36431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Seelenschänder Torek" }
quests[36432] = { id = 36432, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suche nach dem Späher", description = "Wir versuchen noch immer, all unsere Späher ausfindig zu machen. Einer von ihnen, Altauur, nimmt gern die gefährlicheren Missionen an.\n\nEr hat keine Rückmeldung gegeben und ich glaube, wir sollten sicherstellen, dass er sich nicht mehr vorgenommen hat, als er bewältigen kann.", sourceObjective = "Sucht Altauur bei Dionors Ende in Gorgrond.", completion = "D'kaan hat sich um mich Sorgen gemacht? Ich glaube eher, er war besorgt, dass ich mit einem dieser riesigen Biester im Schlepptau ins Lager zurückgekehrt wäre. Nichtsdestotrotz könnte ich hier ein wenig Hilfe gebrauchen...", sourceObjectiveStatus = "unverified-source-field" }
quests[36433] = { id = 36433, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spitzen - Schatz 008 - geschmuggelte Apexisartefakte" }
quests[36434] = { id = 36434, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Himmlische Penny", description = "<Durotan schaut Euch neugierig an.>\n\nAuf Eurer Welt hält man nicht viel von Subtilität, oder?\n\nGeht nur und begrüßt unseren neuen Begleiter. Wir schließen uns Euch an, sobald wir bereit sind.", sourceObjective = "Sprecht mit Penny Kloppertopp an der Wildwacht.", completion = "Ahh, da seid Ihr ja!\n\nPenny Kloppertopp meldet sich zum Dienst, Kommandant.", sourceObjectiveStatus = "unverified-source-field" }
quests[36435] = { id = 36435, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unleserliche Informationen", description = "Die Aufzeichnungen sind unleserlich, aber nach bisherigen Erfahrungen scheint der Text gewöhnlichem Orcisch zu ähneln.\n\nEs ist möglich, dass die Aufzeichnungen strategische Informationen enthalten, die möglicherweise für die Frostwolforcs von Interesse sind.\n\nJemand in Wor'gol könnte vielleicht dabei helfen, den Text zu übersetzen.", sourceObjective = "Schaut Euch in Wor'gol nach jemand um, der bei der Übersetzung der Aufzeichnungen helfen kann.", progress = "<Raleigh schaut von den Schriftrollen hoch.>\n\nKommandant {name}, was führt Euch nach Wor'gol?", completion = "Wir studieren diese Orctexte seit Eurer Ankunft fieberhaft. Gebt mir einen Moment, dann kann ich das für Euch übersetzen.\n\nHmm... Diese Aufzeichnungen scheinen eine Liste von Namen zu enthalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[36436] = { id = 36436, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pflanzen stutzen", description = "An diesem Wildwuchs mag mehr dran sein, als auf den ersten Blick ersichtlich wird, aber wir müssen erst ein wenig den Weg freiräumen, bevor wir der Sache auf den Grund gehen können.\n\nIch würde vorschlagen, dass Ihr einige der wütenderen Verteidiger ausschaltet, um auf der sicheren Seite zu sein.", sourceObjective = "Tötet 12 Verteidiger bei Dionors Ende.", completion = "Ich selbst habe auch einige erlegt, doch hier wachsen ständig neue nach.\n\nWir müssen nach einer anderen Lösung suchen...", sourceObjectiveStatus = "unverified-source-field" }
quests[36437] = { id = 36437, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Botschafter bei den Urtumen", description = "Anscheinend wurde hier vor nicht allzu langer Zeit ein Genesaurier getötet und es hat sich dieser Wuchs gebildet, der die Monster in der Gegend in Aufruhr versetzt. Ich sorge mich um unseren Außenposten.\n\nEs gibt hier ein seltsames Urtum, das in seinem Leid schwelgt, doch es ist nicht feindselig. Vielleicht könntet Ihr ihm seine Geschichte entlocken?", sourceObjective = "Sprecht mit Borkus bei Dionors Ende in Gorgrond.", completion = "Das normale Hin- und Herwogen des Kampfes wurde also von den Saberon gestört. Ich halte es nicht für klug, es dabei zu belassen.\n\nWir sollten versuchen, die Saberon zu infiltrieren und die Dinge zurechtzurücken.", sourceObjectiveStatus = "unverified-source-field" }
quests[36438] = { id = 36438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufmaul gegen Felsen", description = "Die Saberon haben nach Borkus' Angriff ihre Schätze die Anhöhe hinauf gebracht und sich dort verbarrikadiert. Es wird nicht leicht sein, zu ihnen vorzudringen, doch hörte ich, dass Ihr über entsprechende Mittel verfügt.\n\nEiner der Eingänge ist von einem großen Felsen geschützt. Zu groß für Euch oder mich, doch ein Oger mit einem gewaltigen Hammer könnte ihn vielleicht zerbrechen. Ich glaube, Ihr wisst schon, von wem ich hier spreche...", sourceObjective = "Durchbrecht mithilfe des Gladiators Aufmaul die Felsbarriere.", completion = "Ihr habt starke Freunde, {name}. Wir müssen uns beeilen, bevor die Pflanzen realisieren, dass der Weg nun frei ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[36439] = { id = 36439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schredder gegen Saberon", description = "Die Saberon haben nach Borkus' Angriff ihre Schätze die Anhöhe hinauf gebracht und sich dort verbarrikadiert. Es wird nicht leicht sein, zu ihnen vorzudringen, doch hörte ich, dass Ihr über entsprechende Mittel verfügt.\n\nEiner der Eingänge ist von zäher Vegetation bedeckt. Ich glaube, Ihr nennt einen Schredder Euer Eigen? Dann wisst Ihr sicherlich, was zu tun ist...", sourceObjective = "Räumt mit Hilfe des Schredders die Rankenbarriere aus dem Weg.", completion = "Eure Maschine ist klobig, aber wirksam, {name}. Wir müssen uns beeilen, bevor die Pflanzen realisieren, dass der Weg nun frei ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[36440] = { id = 36440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu viele Saberon", description = "Wir nähern uns unseren Zielen, doch eine Schar scharfzahniger Saberon versperrt uns den Weg.\n\nWenn wir hier oben irgend etwas erreichen wollen, müssen meiner Meinung nach einige der aggressiveren von ihnen aus der Welt geschafft werden.", sourceObjective = "Tötet 10 Saberon auf der Dampfnarbenanhöhe.", completion = "Viele finden Schlupflöcher, um Euren Sturm zu überstehen. Das sollte sie Euch vom Leib halten.", sourceObjectiveStatus = "unverified-source-field" }
quests[36441] = { id = 36441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wiederbeschaffung von Eigentum", description = "Ein schwaches grünes Leuchten aus dem Behälter erregt Eure Aufmerksamkeit. Im Inneren befindet sich ein Kräuterbündel, das wahrscheinlich aus dem Dickicht weiter unten gestohlen wurde.\n\nAm besten wäre es, alle von ihnen einzusammeln, sodass die Saberon sich nicht weiter an Pflanzenmagie versuchen können und somit aufhören, die Magnaron zu reizen.", sourceObjective = "Findet 8 Kräuterbündel in Lagern der Saberon bei der Dampfnarbenanhöhe.", progress = "Die Saberon sollten definitiv über keine dieser Kräuter verfügen, die Ihr gefunden habt!", completion = "Gut, dass Ihr diese Kräuter gefunden habt, {name}. Wir dürfen nicht zulassen, dass sie sie weiterhin benutzen. Wer weiß, zu was das führen könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[36442] = { id = 36442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagd auf die Todesblüte", description = "Eure Arbeit hat Früchte getragen. Im Innern der nahegelegenen Höhle lernt ein mächtiger Saberonschamane, mithilfe der von uns gesuchten Todesblüte die Genesauriermagie zu kanalisieren. Das Problem sollte wie folgt gelöst werden: Tötet den Schamanen, nehmt die Todesblüte an Euch und kehrt zu Borkus zurück. Dadurch sollte unser Außenposten sicherer werden.", sourceObjective = "Nehmt Rauchmeister Fletsch auf der Dampfnarbenanhöhe die Todesblüte ab.", progress = "Habt Ihr etwas für mich, kleines Wesen?", completion = "Ihr... Ihr habt mir die Blüte gebracht. Endlich kann sich meine Bestimmung erfüllen!", sourceObjectiveStatus = "unverified-source-field" }
quests[36443] = { id = 36443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die letzte Ruhe für Dionor", description = "Mit dieser Blüte habt Ihr mir einen enorm wertvollen Dienst erwiesen. Jetzt kann ich endlich Dionor ein für alle Mal in den Wildwuchs zurückschicken und diesen Alptraum beenden. Es muss nur noch das Ritual abgehalten werden... bleibt und werdet <Zeuge/Zeugin> von etwas, das Ihr nie wieder erleben werdet...", sourceObjective = "Werdet Zeuge von Borkus' Ritual.", completion = "Endlich ist es vollbracht. Dionor ist fort und seine Brut sollte ihm bald folgen.\n\nIch bin dieses Kampfes müde und habe kein Verlangen mehr, zur Überwucherung zurückzukehren.\n\nVielleicht werde ich dieses Land verlassen und mich auf Reisen begeben, um zu sehen, welche Überraschungen ihr kleinen Wesen noch zu bieten habt...", sourceObjectiveStatus = "unverified-source-field" }
quests[36444] = { id = 36444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spitzen - Schatz 006 - Sprengladungen der Eisernen Horde" }
quests[36445] = { id = 36445, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spitzen - Schatz 015 - Speer der Eisernen Horde" }
quests[36446] = { id = 36446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spitzen - Schatz 016 - Beutel der Ausgestoßenen" }
quests[36447] = { id = 36447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spitzen - Schatz 020 - Korb der Ausgestoßenen" }
quests[36448] = { id = 36448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Personalabbau", description = "Ich war ein Dummkopf, ihm nach dem Fiasko mit dem Familienvermögen der Barovs zu trauen. Ich hätte ihn bei der erstbesten Gelegenheit töten sollen.\n\nUnd jetzt glaubt er, dass er dieses Land nach allem Wertvollen absuchen und mich außen vor lassen kann?!\n\nNein, mein lieber Bruder, diesmal nicht! Es kann nur einen Chef des Barovkonzerns geben, und das bin ich.\n\nMein Bauernfreund, erweist mir diesen Dienst. Findet meinen Bruder Alexi und überbringt ihm eine Kündigung!\n\nIhr findet ihn wahrscheinlich draußen in der Wildnis in der Nähe von kleineren Bäumen.", sourceObjective = "Besorgt den Kopf von Alexi Barov.", progress = "Habt Ihr die... Kündigung abgeliefert?", completion = "<Weldon hält Alexis' Kopf vor sein Gesicht und beginnt zu sprechen.>\n\nDu nichtsnutziger, hinterhältiger Sohn einer Ziege! Deine Gier wird nur noch von meiner übertroffen!\n\nWas Euch angeht, mein Bauernfreund, Ihr habt mir einen guten Dienst erwiesen. Hier ist Eure angemessene Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[36449] = { id = 36449, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Personalabbau", description = "Ich war ein Dummkopf, ihm nach dem Fiasko mit dem Familienvermögen der Barovs zu trauen. Ich hätte ihn bei der erstbesten Gelegenheit töten sollen.\n\nUnd jetzt glaubt er, dass er dieses Land nach allem Wertvollen absuchen und mich außen vor lassen kann?!\n\nNein, mein lieber Bruder, diesmal nicht! Es kann nur einen Chef des Barovkonzerns geben, und das bin ich.\n\nMein Bauernfreund, erweist mir diesen Dienst. Findet meinen Bruder Weldon und überbringt ihm eine Kündigung!\n\nIhr findet ihn wahrscheinlich draußen in der Wildnis in der Nähe von kleineren Bäumen.", sourceObjective = "Besorgt den Kopf von Weldon Barov.", progress = "Wurde meinem Bruder seine Kündigung bereits überbracht?", completion = "<Alexi hält Weldons Kopf vor sein Gesicht und beginnt zu sprechen.>\n\nDu nichtsnutziger, hinterhältiger Sohn einer Ziege! Deine Gier wird nur noch von meiner übertroffen!\n\nWas Euch angeht, mein Bauernfreund, Ihr habt mir einen guten Dienst erwiesen. Hier ist Eure angemessene Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[36450] = { id = 36450, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spitzen - Schatz 028 - Ritualgebräu der Sethekk" }
quests[36451] = { id = 36451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spitzen - Schatz 033 - Handwerkerhammer" }
quests[36452] = { id = 36452, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Funktionieren Spawntracking und Zauber-Bilder?", description = "Hier ist ein bisschen Text.", sourceObjective = "Benutzt das Dingens um zu sehen, wie das Zauber-Bild durch die Magie des Spawntracking scheint.", sourceObjectiveStatus = "unverified-source-field" }
quests[36453] = { id = 36453, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spitzen - Schatz 038 - Münzknausers Bezahlung" }
quests[36454] = { id = 36454, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spitzen - Schatz 039 - Trockenhüte" }
quests[36455] = { id = 36455, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spitzen - Schatz 040 - Durchnässter Sack" }
quests[36456] = { id = 36456, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spitzen - Schatz 045 - Schredderteile" }
quests[36457] = { id = 36457, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Umgehen der Sicherheitsmaßnahmen", description = "Oh du meine Güte!\n\nDas ist eine Liste von Gefangenen, die anscheinend auf ihren Abtransport warten... oder sogar ihre Hinrichtung!\n\nEinen Namen auf der Liste erkenne ich: den meines Meisters!\n\nIch habe auf seine Rückkehr gewartet, aber wie es scheint, ist er dem Feind in die Hände gefallen.\n\nDas ist eine Katastrophe! Bitte, {name}, wir müssen ihn retten!\n\nLaut diesen Aufzeichnungen wurde er nach Grom'gar gebracht, weit im Osten von hier.\n\nEinen Augenblick... Ich glaube, ich habe genau das Richtige, damit Ihr unbemerkt dort eindringen könnt...", sourceObjective = "Schleicht Euch nach Grom'gar hinein, indem ihr Raleighs Prestigekarte benutzt.", completion = "Kennt Ihr den Trick dabei, einen Haufen Orcs zum Narren zu halten? Man muss nur hin und wieder alle Karten in der Hand halten!", sourceObjectiveStatus = "unverified-source-field" }
quests[36458] = { id = 36458, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spitzen - Schatz 055 - Liegen gelassene Spitzhacke" }
quests[36459] = { id = 36459, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spitzen - Schatz 056 - Entferntes Sägeblatt" }
quests[36460] = { id = 36460, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Mauer, auf der Lauer sitzt ein kleiner Zünder", description = "Hört zu.\n\nAls ich hergeflogen bin, hab' ich die Gelegenheit dazu genutzt, eine geeignete Verteidigungsposition auszukundschaften.\n\nDirekt auf der anderen Seite dieser Felsen gibt es eine Lichtung, die ideal wäre, um einen Unterschlupf zu bauen. Ich hab' sogar einige Baupläne mitgebracht, die uns helfen werden, hier Fuß zu fassen!\n\nDas ist nicht zu anmaßend, oder?\n\nNun, wie dem auch sei. Wenn Ihr bereit seid, betätigt einfach diesen Zünder.", sourceObjective = "Benutzt Pennys Zünder, um die Mauer in die Luft zu sprengen.", completion = "Vielleicht stellt sich diese kleine Kreatur ja doch noch als nützlich heraus.", sourceObjectiveStatus = "unverified-source-field" }
quests[36461] = { id = 36461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach dem Edelsteinexperten", sourceObjective = "Sucht in Wor'gol nach dem Besitzer des Anhängers.", sourceObjectiveStatus = "unverified-source-field" }
