quests[36468] = { id = 36468, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfolgungsquest: Schatzkarte" }
quests[36469] = { id = 36469, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haustiere gegen Ungeziefer", description = "Ich hab versucht, den Laden für Eure Haustiere fertig zu mach'n, aber als wir die Garnison gebaut hab'n, sind wir auf 'n paar fiese Plagegeister gestoß'n. Ich wollt' sie selber erledig'n, aber sie war'n 'ne Nummer zu zäh.\n\nSchlagt die wütende Karotte im Garten, die Ratte, die unser Essen frisst un' die störrische Wasserkreatur, die die Fischer belästigt. Wenn Ihr das schafft, kann ich die Menagerie für Euch fertig bau'n.", sourceObjective = "Vernichtet die drei Ungezieferkreaturen in Eurer Garnison.", completion = "Gut gemacht, Bruder. Hoff'ntlich gefällt deinen Viechern ihr neues Zuhause.", sourceObjectiveStatus = "unverified-source-field" }
quests[36470] = { id = 36470, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spitzen - Vignette Boss 006 - Faulhut" }
quests[36471] = { id = 36471, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein neuer Herausforderer des Dunkelmonds!", description = "Schaut mich an, jetzt mein Pferd, jetzt wieder mich... bin ich nicht der beeindruckendste Haustierkämpfer, den Ihr je gesehen habt?\n\nSchaut Euch jetzt meinen Kompagnon da drüben an. Sitzt er auf einem Pferd? Natürlich nicht! Besteht sein Hut aus Feuerwerk? Nicht in einer Million Jahre! Alles an mir ist beeindruckender, von der Farbe meines Mantels bis zu meinem Nachnamen, den ich mir selbst ausgedacht habe.\n\nWagt Ihr es, dem mächtigen Christoph Willikens Dennis Ragnaros von Feasel dem Ersten entgegenzutreten?\n\nIch sehe schon, wie Ihr zittert!", sourceObjective = "Besiegt Christoph von Feasel in einem Haustierkampf.", completion = "Nächstes Mal werde ich es Euch nicht so leicht machen!", sourceObjectiveStatus = "unverified-source-field" }
quests[36472] = { id = 36472, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spitzen - Vignette Boss 028 - Uralte Wespe" }
quests[36473] = { id = 36473, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leidensgrat" }
quests[36474] = { id = 36474, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Klingenflor", description = "Die Schamanin des Lachenden Schädels, Kaz, hat sich davongemacht, während wir auf dem Weg hierhin waren.\n\nSie behauptete, im Dschungel südlich von hier nach mehr von ihrem Volk Ausschau zu halten.\n\nDraka hat darauf bestanden, sie zu begleiten, um uns vor Verrat zu schützen.\n\nKommandant, falls Kaz die Wahrheit sagt, dann werden sie und Draka all die Hilfe benötigen, die sie bekommen können.\n\nWerdet Ihr Euch ihnen anschließen? Weit können sie noch nicht sein.\n\nDies könnte der perfekte Test für Eure neuen Schredder- und Sägewerkressourcen werden.", sourceObjective = "Findet Draka und Kaz beim Klingenflor.", completion = "Mein Mann hat Euch geschickt, nicht wahr?\n\nEigentlich würde ich darüber lachen, aber angesichts dieser Gräuel können Kaz und ich jede Hilfe brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36475] = { id = 36475, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestohlene Erklärung", description = "Kommandant, Ihr und Raleigh habt gute Arbeit geleistet, als Ihr mich gefunden habt, aber ich bin genau dort, wo ich hingehöre.\n\nWir haben seit unserer Ankunft unermüdlich gearbeitet und versucht, diese Texte der Draenei zu knacken.\n\nIch dachte wirklich, ich hätte diese Schriftrollen verstanden, aber dann haben sie mich in letzter Sekunde erwischt!\n\nBitte, Ihr müsst mir helfen... Auf dem Hügel im Osten findet Ihr das Zelt des Meisterbelagerungsschmieds.\n\nWenn Ihr Euch die Dokumente aus seiner Kiste schnappen könntet und vielleicht auch seinen Schlüssel, dann habe ich endlich genug, um diese Sprache zu übersetzen.", sourceObjective = "Plündert den Inhalt von Meisterbelagerungsschmied Uratoks Schließtruhe.", progress = "Ein Buch mit Gedichten? Ich überlasse das für den Moment Euch...", completion = "{name}, das ist es, DAS IST ES! Gebt mir nur einen Moment Zeit, während ich alles durchsehe.\n\nHmm... Ich glaube, es gibt einige Dinge hier, die Ihr nützlich finden könntet. Hier, nehmt diese Pläne mit.\n\nMacht Euch keine Sorgen um mich. Ich schaue mich nur noch einmal kurz um, bevor ich hier rausschleiche.", sourceObjectiveStatus = "unverified-source-field" }
quests[36476] = { id = 36476, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Südliche Gronnschlucht" }
quests[36477] = { id = 36477, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gebrochene Versprechen", description = "Ein sehr zerkratzter Ring mit schwachen Blutspuren.\n\nJemand auf dem Dunkelmond-Jahrmarkt könnte vielleicht mehr Informationen über diesen Gegenstand haben.", sourceObjective = "Findet jemanden auf dem Dunkelmond-Jahrmarkt, der sich für den Ring interessieren könnte.\n\nBereitgestellter Gegenstand:", completion = "Ah, wie ich sehe, habt Ihr meine Lieblinge gefunden. Hübsch, nicht wahr? Schade nur, dass der Vorgang sie immer so... in den Wahnsinn treibt.\n\nDer Ring gehört natürlich Euch. Könnt Ihr sie flüstern hören? Wundervoll.", sourceObjectiveStatus = "unverified-source-field" }
quests[36478] = { id = 36478, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spitzen - Vignette 020 - Schattenrinde" }
quests[36479] = { id = 36479, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spitzen - Vignette 021 - Nachtschlund" }
quests[36480] = { id = 36480, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tal der Zerstörung" }
quests[36481] = { id = 36481, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderung des Feuervogels", description = "Seid Ihr bereit, Euch hoch in die Lüfte zu schwingen und Euch der Herausforderung des Feuervogels zu stellen? Das ist großartig!\n\nSammelt einfach 15 Ringe, um zu gewinnen! Sprecht mich an, wenn Ihr bereit seid, abzuheben!", sourceObjective = "Sammelt 15 Ringe im Flug.", progress = "Wie war der Flug?", completion = "Wow, tolle Flugkünste, Ihr seid ein Ass! Hier ist Euer Preis!", sourceObjectiveStatus = "unverified-source-field" }
quests[36482] = { id = 36482, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein grüner Ogron?", description = "Kaz hat immer gesagt, dass grüne Ogron schlecht sind.\n\nDie Botani hier haben einen grünen Ogron, und der ist richtig gemein.\n\nEr war stark genug, die gesamte Jagdgesellschaft meines Vaters auszuschalten.\n\nSeid Ihr stark genug, ihn zu töten?", sourceObjective = "Tötet den befallenen Ogron.", completion = "Juhuu! Macht ihn platt! Macht ihn so richtig platt!", sourceObjectiveStatus = "unverified-source-field" }
quests[36483] = { id = 36483, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zusammentrieb der Kampfhaustiere", description = "Scheinbar haben wir im Kampfzwinger heute Besucher, die auf einen Kampf aus sind. Warum zeigt Ihr ihnen nicht, wie <ein wahrer Meister/eine wahre Meisterin> des Haustierkampfs sich schlägt?", sourceObjective = "Besiegt die Haustiere in der Kampfarena.", progress = "Die Biester haben ziemlich zäh ausgesehen. Wie ist es gelaufen?", completion = "Ich wusste, dass Ihr es schaffen könnt, mein Junge.", sourceObjectiveStatus = "unverified-source-field" }
quests[36488] = { id = 36488, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diebische Zwerge", description = "Schlitzer ist den Artefakten auf der Spur, die die Zwerge gestohlen haben. Er hat die Nase eines Wolfes, wenn es darum geht, Fährten im Dschungel zu verfolgen.\n\nFolgt der Schlucht gen Süden, bis Ihr ihn findet.\n\nDie Wolfkönigin und ich werden hier noch ein wenig mehr Schaden anrichten, bevor wir aufbrechen.\n\nWir folgen Euch, so schnell wir können.", sourceObjective = "Findet Schlitzer bei der Bastionsklippe.", completion = "Wow. Diese... \"Zwerge\"... sind wahrhafte Meister darin, sowohl die Botani als auch die Goren wütend zu machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36489] = { id = 36489, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf die Grube", description = "Die Eiserne Horde lagert ihre Waffen und Munitionsvorräte außerhalb der Gießerei. Durch ihre Kampagne in ganz Draenor sind ihre Vorratslager angreifbar geworden. Begebt Euch dorthin und richtet so viel Chaos wie möglich an. Und verwendet auch ein bisschen ihrer eigenen Munition gegen sie, wenn sie das Zeug schon einfach herumliegen lassen!", sourceObjective = "Zerstört das Waffenlager der Eisernen Horde und schaltet so viele von ihnen aus wie möglich.", sourceObjectiveStatus = "unverified-source-field" }
quests[36490] = { id = 36490, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf die Säulen des Schicksals" }
quests[36491] = { id = 36491, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf die Säulen des Schicksals" }
quests[36492] = { id = 36492, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garrison Pet Battle" }
quests[36493] = { id = 36493, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfolgungsquest: Kann Othaars Tür öffnen" }
quests[36494] = { id = 36494, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachricht aus Talador", description = "Rokhan lässt mitteilen, dass Ihr am Frostwall gebraucht werdet. Die Eiserne Horde ist an der Küste von Talador gelandet.", sourceObjective = "Sprecht mit Rokhan in Eurer Garnison im Frostfeuergrat.", completion = "Willkommen zurück, Boss.", sourceObjectiveStatus = "unverified-source-field" }
quests[36495] = { id = 36495, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachricht aus Talador", description = "Bodrick Grau lässt Euch aus Eurer Garnison mitteilen, dass eine Flotte der Eisernen Horde an der Küste von Talador gesichtet wurde.\n\nWir dürfen nicht zulassen, dass sie Shattrath zerstören.", sourceObjective = "Sprecht mit Bodrick Grau in Eurer Garnison im Schattenmondtal.", completion = "Willkommen zurück, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[36498] = { id = 36498, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasion der Eisernen Horde", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Verteidiger Maraad am Zerschmetterten Brückenkopf in den Verwüsteten Landen einzufinden.\n\nBenutzt das Portal beim Magiersanktum in Sturmwind, um Euch direkt an die Front zu begeben.\n\nDiese neue Bedrohung ist bekannt als die Eiserne Horde. Sie haben das Dunkle Portal übernommen und müssen aufgehalten werden.\n\nFür den Ruhm und die Ehre der Allianz!", sourceObjective = "Sprecht mit Verteidiger Maraad am Zerschmetterten Brückenkopf in den Verwüsteten Landen.", completion = "Die Lage hier ist prekär, {name}. Wir haben viel zu besprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36499] = { id = 36499, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasion der Eisernen Horde", description = "An alle tauglichen Mitglieder der Horde ergeht hiermit der Befehl, sich bei Thrall in den Verwüsteten Landen zu melden.\n\nBenutzt das Portal in der Gasse in Orgrimmar, um Euch direkt an die Front zu begeben.\n\nDiese neue Bedrohung ist nur als die Eiserne Horde bekannt. Sie haben das Dunkle Portal übernommen und müssen aufgehalten werden!\n\nAntwortet dem Ruf des Schicksals!", sourceObjective = "Sprecht mit Thrall an der Zerschmetterten Klippe in den Verwüsteten Landen.", completion = "Die Lage hier ist prekär, {name}. Wir haben viel zu besprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36500] = { id = 36500, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Klingenflor" }
quests[36501] = { id = 36501, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasion der Eisernen Horde", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Verteidiger Maraad am Zerschmetterten Brückenkopf in den Verwüsteten Landen einzufinden.\n\nZu den Docks vor der Feste Nordwacht gelangt Ihr, indem Ihr das Schiff von Beutebucht nach Ratschet nehmt und dann entlang der Küste in südliche Richtung reist.\n\nFür den Ruhm und die Ehre der Allianz!" }
quests[36502] = { id = 36502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruhmestrophäe: Biolante", description = "Der Sieg über Biolante hat Euch eine Trophäe eingebracht, die es würdig ist, in Eurem Außenposten zur Schau gestellt zu werden. \n\nBringt sie zu Maraad, um Euren Ruhm zu mehren!", sourceObjective = "Bringt die Trophäe zu Maraad am Hochpass in Gorgrond.\n\nBereitgestellter Gegenstand:", completion = "Ich habe schon früher gesehen, wie Pflanzen die gefährliche Hydra imitieren, aber das Aussehen noch verbessern? Nur in Gorgrond... Ausgezeichnete Arbeit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[36503] = { id = 36503, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruhmestrophäe: Biolante", description = "Der Sieg über Biolante hat Euch eine Trophäe eingetragen, die der Anerkennung würdig ist.\n\nBringt dies zu Durotan in der Wildwacht.", sourceObjective = "Bringt die Trophäe zu Durotan in der Wildwacht in Gorgrond.\n\nBereitgestellter Gegenstand:", completion = "Hier werden selbst Pflanzen zu bösartigen Monstern. Biolante war eines der schlimmsten – als Pflanze regungslos, bis man ihr zu nahe gekommen ist.\n\nEin passendes Ende für ein solches Ungeheuer...", sourceObjectiveStatus = "unverified-source-field" }
quests[36504] = { id = 36504, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immermornquellen" }
quests[36505] = { id = 36505, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Umhang eines Kriegers", description = "Dieser Umhang hat schon bessere Zeiten gesehen, aber man sieht immer noch, dass er von einem fähigen Handwerker hergestellt wurde. Jeder gewöhnliche Umhang wäre bestimmt schon längst auseinandergefallen.\n\nVielleicht könnte Euch einer der Frostwolforcs in Wor'gol dabei helfen, ihn wieder instand zu setzen.", sourceObjective = "Sucht in Wor'gol einen Frostwolflederverarbeiter, der Euch helfen kann.", progress = "Guten Tag, {race}. Kann ich für Euch etwas reparieren?", completion = "Das ist ein feiner Umhang! Leider fehlen uns zurzeit die Ressourcen, um Ähnliches zu fertigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36506] = { id = 36506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Großartige Orcbeute für Zauberwirker" }
quests[36507] = { id = 36507, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Orcskelett" }
quests[36508] = { id = 36508, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gehört der zu Euch?", description = "Die hab ich in der Nähe herumlungernd gefunden. Sie behauptet, eine Verbündete von Euch zu sein.\n\nIst das wahr? Oder soll ich sie langsam über offenem Feuer kochen?", sourceObjective = "Sprecht mit Rexxar und bürgt für Rangari Erdanii.", completion = "Danke, dass Ihr für mich gebürgt habt, Kommandant.", sourceObjectiveStatus = "unverified-source-field" }
quests[36509] = { id = 36509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Hydraschatzhaufen" }
quests[36510] = { id = 36510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuerammonit", description = "Wir müssen den Garnisonsteich mit einheimischen Fischen bevölkern. Könntet Ihr vielleicht am Frostfeuergrat nach geeigneten Fischen suchen? Wenn Ihr sie habt, müsst Ihr sie aufschneiden und nach Eiern sehen.", sourceObjective = "Ron Ashton möchte, dass Ihr 10 Eier von Feuerammoniten in Frostfeuergrat einsammelt.", progress = "Beißen sie?", completion = "Die sind genau richtig, {name}! Vielen Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[36511] = { id = 36511, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kieferloser Schleicher", description = "Wir müssen den Garnisonsteich mit einheimischen Fischen bevölkern. Könntet Ihr vielleicht in Gorgrond nach geeigneten Fischen suchen? Wenn Ihr sie habt, müsst Ihr sie aufschneiden und nach Eiern sehen.", sourceObjective = "Ron Ashton möchte, dass Ihr in Gorgrond die Eier von 10 kieferlosen Schleichern einsammelt.", progress = "Beißen sie?", completion = "Die sind genau richtig, {name}! Vielen Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[36512] = { id = 36512, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gemeinsam sind wir stark", sourceObjective = "Auchindoun wäre in die Hände der Dämonen gefallen, wenn Ihr nicht gewesen wärt. Sogar die Blutelfen hätten das nicht geändert. Ich weiß nicht, wie wir das jemals wiedergutmachen sollen.\n\n<Tuulanis Gesicht hellt sich auf.>\n\nIch hab's! Wir sind verwandte Geister, {name}. Ich kann es spüren! Wie wäre es, wenn ich etwas bei Euch bleibe?\n\nIch muss zwar meinen Pflichten in Auchindoun nachkommen, aber das schaffe ich schon. Was sagt Ihr, {name}? Das wird großartig!", sourceObjectiveStatus = "unverified-source-field" }
quests[36513] = { id = 36513, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dicker Schläfer", description = "Wir müssen den Garnisonsteich mit einheimischen Fischen bevölkern. Könntet Ihr vielleicht in Nagrand nach geeigneten Fischen suchen? Wenn Ihr sie habt, müsst Ihr sie aufschneiden und nach Eiern sehen.", sourceObjective = "Ron Ashton möchte, dass Ihr 10 Eier von dicken Schläfern in Nagrand einsammelt.", progress = "Beißen sie?", completion = "Die sind genau richtig, {name}! Vielen Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[36514] = { id = 36514, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blinder Seestör", description = "Wir müssen den Teich der Garnison mit einheimischen Fischen füllen. Ich möchte, dass Ihr die Gewässer im Schattenmondtal nach Fischen absucht, mit denen wir sie bevölkern können. Sobald Ihr einen Fisch habt, müsst Ihr sie aufschneiden und in ihnen nach Eiern suchen.", sourceObjective = "Ron Ashton möchte, dass Ihr 10 Eier von blinden Seestören im Schattenmondtal einsammelt.", progress = "Beißen sie?", completion = "Die sind genau richtig, {name}! Vielen Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[36515] = { id = 36515, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwarzwasserpeitschflosse", description = "Wir müssen den Garnisonsteich mit einheimischen Fischen bevölkern. Könntet Ihr vielleicht in Talador nach geeigneten Fischen suchen? Wenn Ihr sie habt, müsst Ihr sie aufschneiden und nach Eiern sehen.", sourceObjective = "Ron Ashton möchte, dass Ihr 10 Eier von Schwarzwasserpeitschflossen aus Talador beschafft.", progress = "Beißen sie?", completion = "Die sind genau richtig, {name}! Vielen Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[36516] = { id = 36516, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schnippschnapp!", description = "Nach allem, was Ihr für uns getan habt, würde ich Euch gerne helfen. Bedauerlicherweise fehlen mir die Materialien, um dies fachgerecht reparieren zu können.\n\nBenutzt mein Messer, um ein paar Felle von Grollhufen zu beschaffen, die nahe der Spitze herumstreunen, und sucht auch etwas Rußkrautpech, um sie richtig räuchern zu können.\n\nLeider haben sich in dem einzigen mir bekannten Gebiet, in dem Rußkrautpech wächst, diese elenden Oger breitgemacht. Ihr solltet Euch also auf einen Kampf vorbereiten, {name}.\n\nKehrt zu mir zurück, wenn Ihr alles beschafft habt, und ich werde Euch mit Freuden Euren Umhang reparieren.", sourceObjective = "Beschafft die zur Reparatur des Umhangs benötigten Materialien.", progress = "Konntet Ihr die Materialien beschaffen, {name}?", completion = "Ihr seid von Kopf bis Fuß mit Ruß bedeckt, {name}!\n\nIch werde Euch wie versprochen bei der Reparatur Eures Umhangs helfen. Ich habe hier noch ein paar weitere Gegenstände, die Ihr vielleicht nützlich finden werdet.\n\nIhr könnt mich jederzeit wieder besuchen!", sourceObjectiveStatus = "unverified-source-field" }
quests[36517] = { id = 36517, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefenschluckaal", description = "Wir müssen den Garnisonsteich mit einheimischen Fischen bevölkern. Könntet Ihr vielleicht bei den Spitzen von Arak nach geeigneten Fischen suchen? Wenn Ihr sie habt, müsst Ihr sie aufschneiden und nach Eiern sehen.", sourceObjective = "Ron Ashton möchte, dass Ihr 10 Eier von Tiefenschluckaalen in den Spitzen von Arak einsammelt.", progress = "Beißen sie?", completion = "Die sind genau richtig, {name}! Vielen Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[36518] = { id = 36518, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der wahre Weg", sourceObjective = "Wow... Ich habe noch nie jemanden so kämpfen sehen. Das war... beeindruckend.\n\nIch bin jetzt nicht in der Verfassung, mich Lady Liadrin und den anderen in Auchindoun anzuschließen. Ihr habt auf dieser Welt aber eine ganze Festung. Könnte ich dorthin gehen und mich eine Weile ausruhen? Vielleicht meine Rüstung reparieren?\n\nIch bleibe eine Weile bei Euch und schließe mich Euren Streitkräften als Zeichen meiner Dankbarkeit an. Liadrin wird das schon verstehen... Wir sind schließlich alle auf derselben Seite, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[36519] = { id = 36519, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der wahre Weg", sourceObjective = "Ich habe noch nie jemanden so kämpfen sehen, {name}.\n\nLeider bin ich nicht in der Verfassung, mich jetzt den Auchenai zur Verteidigung Auchindouns anzuschließen. Ich hörte Geschichten über Eure Festung im Schattenmondtal. Kann ich vielleicht dort meine Rüstung reparieren?\n\nVielleicht... könnte ich noch ein wenig länger dort bleiben? Ich denke, Ihr könnt mir noch viel beibringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36520] = { id = 36520, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keulenschwanzbecken" }
quests[36521] = { id = 36521, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Rylakei" }
quests[36522] = { id = 36522, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Solidarität im Tod", sourceObjective = "Ich mag gefallen sein, aber ich werde nicht in Vergessenheit geraten.\n\nIch flehe Euch an, erlaubt mir, hierzubleiben und in Eurer Armee zu dienen. Bralok hat mir das Leben genommen, aber mein Geist steht in voller Stärke vor Euch.\n\nIch muss die Eiserne Horde aufhalten, {name}, und ich weiß, Ihr seid der Einzige, der mir dabei helfen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[36523] = { id = 36523, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein grüner Ogron?", description = "Die Botani haben sich einen grünen Ogron besorgt. Einen grünen Ogron!\n\nIch hab' vielleicht nicht sonderlich viel Ahnung von diesen Pflanzenleuten, aber das bedeutet sicher nichts Gutes.\n\nOb Ihr den wohl ausschalten könnt?", sourceObjective = "Tötet den befallenen Ogron.", completion = "Zuckt er noch? Ich glaube, ich hab' ihn noch zucken sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36524] = { id = 36524, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garrison Max-level Choice Reward Summary: Solo" }
